select case when rating >= 4.1 then 'LARGE' else 'SMALL' end as rating_tier, count(case when country = 'SG' then 1 end) as sg_count, sum(case when city = 'Berlin' then rating else 0 end) as berlin_rating, count(*) as num_rows, count_if(city = 'New York') as new_york_events, count(case when country = 'DE' then 1 end) as de_count, count(case when city = 'New York' then 1 end) as new_york_count from suppliers group by case when rating >= 4.1 then 'LARGE' else 'SMALL' end order by num_rows desc;
